import { Effect } from "effect"
/** Completes stored credentials lazily. */
export const run = (config: { complete?: (values: { token: string }) => Effect.Effect<{ token: string }> | undefined }, values: { token: string }) => Effect.gen(function* () {
  const complete = config.complete?.(values) ?? Effect.succeed(values)
  return yield* complete
})
